const $=s=>document.querySelector(s);const main=$('#main');
const categories=[['Paper & printing','A4 paper, photocopy paper and everyday print essentials.','paper'],['Writing essentials','Pens, pencils, highlighters and markers.','pens'],['Files & office supplies','Files, folders and supplies for an organised office.','files'],['Books & notebooks','Exercise books and notebooks for learning and work.','books'],['School stationery packs','Prepare a list by grade, class or learning programme.','pack'],['Art & craft','Creative essentials for classrooms and projects.','art'],['Rulers & geometry','Rulers, geometry sets and measuring essentials.','ruler'],['Calculators','Share the model and functions your learners or team need.','calc']];
function icon(kind){const a={paper:'<path d="M28 15h58l17 17v53H28z" fill="#fff" stroke="#a5b2bc"/><path d="M86 15v19h17" fill="#dfb454"/><path d="M17 27v68h66" fill="none" stroke="#06264d" stroke-width="8"/><path d="M40 49h47M40 60h47M40 71h31" stroke="#b7c3cc" stroke-width="3"/>',pens:'<g transform="rotate(20 60 50)"><path d="M32 15h12v58l-6 13-6-13z" fill="#dfb454"/><path d="M56 10h13v65l-7 13-6-13z" fill="#06264d"/><path d="M82 22h10v52l-5 12-5-12z" fill="#819a9c"/><path d="M32 25h12M56 23h13M82 33h10" stroke="white" stroke-width="3"/></g>',files:'<rect x="17" y="24" width="27" height="63" rx="2" fill="#06264d"/><rect x="47" y="16" width="27" height="71" rx="2" fill="#dfb454"/><rect x="77" y="28" width="27" height="59" rx="2" fill="#7e999d"/><path d="M25 36h11M55 29h11M85 40h11" stroke="white" stroke-width="4"/><circle cx="30" cy="73" r="4" fill="white"/><circle cx="60" cy="73" r="4" fill="white"/><circle cx="90" cy="73" r="4" fill="white"/>',books:'<path d="M17 62h84v19H17z" fill="#06264d"/><path d="M22 44h78v18H22z" fill="#dfb454"/><path d="M30 25h66v19H30z" fill="#829b9e"/><path d="M27 70h65M31 52h59M39 33h47" stroke="#fff" stroke-width="4"/>',pack:'<path d="M27 38q0-17 17-17h35q17 0 17 17v48H27z" fill="#06264d"/><path d="M48 21v-6h26v6" fill="none" stroke="#b98e37" stroke-width="5"/><rect x="38" y="55" width="48" height="24" rx="5" fill="#dfb454"/><path d="M40 45h42M49 65h25" stroke="white" stroke-width="3"/>',art:'<path d="M29 48h62l-7 39H36z" fill="#dfb454"/><path d="M43 15l5 36M66 12v38M88 20L76 51" stroke="#06264d" stroke-width="7"/><path d="M39 6l3 12M66 3v12M92 10l-5 14" stroke="#819a9c" stroke-width="10"/>',ruler:'<path d="M21 83L100 9v74z" fill="#dfb454"/><path d="M49 71l38-35v35z" fill="#efeee8"/><path d="M36 73l-5-5M47 63l-5-5M58 53l-5-5M69 43l-5-5M80 33l-5-5" stroke="#06264d" stroke-width="2"/>',calc:'<rect x="31" y="9" width="62" height="80" rx="6" fill="#06264d"/><rect x="41" y="19" width="42" height="20" rx="2" fill="#d4dfd0"/><path d="M42 51h8m8 0h8m8 0h8M42 64h8m8 0h8m8 0h8M42 77h8m8 0h8" stroke="white" stroke-width="5"/><path d="M75 70h8v13h-8z" fill="#dfb454"/>'};return `<svg viewBox="0 0 120 100" aria-hidden="true">${a[kind]}</svg>`}
const heroArt=`<svg viewBox="0 0 560 500" role="img" aria-label="Illustration of notebooks, paper, pencils and a ruler arranged on a desk"><defs><linearGradient id="bg" x2="1" y2="1"><stop stop-color="#204969"/><stop offset="1" stop-color="#0b2d4c"/></linearGradient><linearGradient id="gold" x2="1" y2="1"><stop stop-color="#f3d695"/><stop offset="1" stop-color="#c19a49"/></linearGradient><filter id="shadow"><feDropShadow dx="0" dy="16" stdDeviation="15" flood-opacity=".23"/></filter></defs><circle cx="305" cy="240" r="208" fill="url(#bg)"/><circle cx="305" cy="240" r="180" fill="none" stroke="#7590a1" stroke-opacity=".15"/><g transform="rotate(-13 210 270)" filter="url(#shadow)"><rect x="96" y="112" width="187" height="282" rx="6" fill="#e6e4dd"/><rect x="86" y="102" width="187" height="282" rx="6" fill="#dfb454"/><path d="M107 105v275" stroke="#ad8231" stroke-width="3"/><rect x="129" y="155" width="111" height="80" fill="#f7f4eb"/><text x="184" y="188" text-anchor="middle" fill="#06264d" font-family="Georgia" font-size="18">Ideas start</text><text x="184" y="213" text-anchor="middle" fill="#06264d" font-family="Georgia" font-size="18">here.</text></g><g transform="rotate(12 350 280)" filter="url(#shadow)"><rect x="263" y="168" width="174" height="225" rx="4" fill="#d1d6d8"/><rect x="254" y="158" width="174" height="225" rx="4" fill="#faf9f3"/><path d="M278 191h125M278 210h125M278 229h125M278 248h125M278 267h125M278 286h125M278 305h125M278 324h125M278 343h125" stroke="#ccd7de" stroke-width="1.5"/><path d="M282 159v224" stroke="#dfb454" stroke-width="2"/><path d="M265 169h-14m14 20h-14m14 20h-14m14 20h-14m14 20h-14m14 20h-14m14 20h-14m14 20h-14m14 20h-14m14 20h-14" stroke="#859baa" stroke-width="4"/></g><g transform="rotate(24 400 150)"><path d="M389 56h14v205l-7 19-7-19z" fill="url(#gold)"/><path d="M389 56h14v26h-14" fill="#f2eee4"/><path d="M393 273l3 7 3-7" fill="#06264d"/><path d="M412 84h13v183l-6 15-7-15z" fill="#829d9c"/><path d="M412 84h13v18h-13" fill="#d8dcda"/></g><g transform="rotate(-17 365 389)"><rect x="264" y="381" width="226" height="30" rx="2" fill="#e2c17d"/><path d="M277 381v13m13-13v8m13-8v13m13-13v8m13-8v13m13-13v8m13-8v13m13-13v8m13-8v13m13-13v8m13-8v13m13-13v8m13-8v13m13-13v8m13-8v13m13-13v8" stroke="#7d682f" stroke-width="1.5"/></g><circle cx="114" cy="400" r="5" fill="#dfb454"/><path d="M457 110h17m-8-8v17" stroke="#dfb454" stroke-width="2"/><text x="116" y="451" fill="#bdcbd7" font-family="Arial" font-size="10" letter-spacing="3">READY FOR YOUR NEXT CHAPTER</text></svg>`;
let items=[];let formData={};let step=0;let selectedFiles=[];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),2600)}
function updateCount(){document.querySelectorAll('.basket-count').forEach(e=>e.textContent=items.length?`(${items.length})`:'')}
function cards(filter=''){return categories.filter(c=>c[0].toLowerCase().includes(filter.toLowerCase())).map(c=>`<article class="category"><div class="category-visual">${icon(c[2])}</div><h3>${c[0]}</h3><p>${c[1]}</p><button data-add="${c[2]}">Add to quote list <span aria-hidden="true">＋</span></button></article>`).join('')}
function cta(){return `<section class="cta"><div class="wrap"><div><h2>Your list. One clear next step.</h2><p>Share what you need, where it needs to go and when.</p></div><a class="btn dark" href="#quote">Prepare a quote request ↗</a></div></section>`}
function home(){return `<section class="hero"><div class="wrap hero-grid"><div><div class="eyebrow">Stationery supply · South Africa</div><h1>For the work<br>ahead. <em>And the<br>ideas to come.</em></h1><p>Stationery for businesses, public-sector buyers and schools. Start with your list. Plan your supply with Lepetse.</p><div class="actions"><a class="btn" href="#quote">Request a quote ↗</a><a class="btn outline" href="#stationery">Explore stationery</a></div><p class="fine">Once-off requirements · Office replenishment · School packs</p></div><div class="art">${heroArt}<div class="art-note"><b>From a single list to a clearer plan.</b>Specify. Quote. Approve. Arrange delivery.</div></div></div></section><div class="benefits"><div class="wrap"><span><i>↗</i> Itemised quotation requests</span><span><i>▤</i> List uploads and bulk requirements</span><span><i>⌖</i> Delivery arrangements by location</span></div></div><section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Built around your buying needs</span><h2>Different buyers.<br>The same attention to detail.</h2></div><p>Whether you are equipping an office, responding to a procurement requirement or preparing a classroom, start with the route that fits.</p></div><div class="buyers"><article class="buyer"><span class="number">01 /</span><h3>For businesses</h3><p>Everyday office essentials, bulk lists and recurring stationery requirements.</p><a class="text-link" href="#business">Business supply ↗</a></article><article class="buyer"><span class="number">02 /</span><h3>For government</h3><p>Share formal RFQs, specifications and procurement deadlines for assessment.</p><a class="text-link" href="#government">Government procurement ↗</a></article><article class="buyer"><span class="number">03 /</span><h3>For schools</h3><p>Exercise books, learning essentials and stationery packs built around your list.</p><a class="text-link" href="#schools">School stationery ↗</a></article></div></div></section><section class="section soft"><div class="wrap"><div class="section-head"><div><span class="eyebrow">The everyday essentials</span><h2>A well-supplied day starts here.</h2></div><a class="text-link" href="#stationery">View all categories ↗</a></div><div class="category-grid">${cards().split('</article>').slice(0,4).join('</article>')}</article></div></div></section><section class="section"><div class="wrap"><span class="eyebrow">A straightforward process</span><h2>From your list to the next step.</h2><div class="process">${[['Send your requirements','Add items or attach your stationery list.'],['Confirm the details','Specify quantities, pack sizes, location and timing.'],['Review your quotation','Check the itemised offer and proposed arrangements.'],['Approve and arrange','Confirm through your purchasing process before fulfilment.']].map((a,i)=>`<div class="step"><b>0${i+1}</b><h3>${a[0]}</h3><p>${a[1]}</p></div>`).join('')}</div></div></section><section class="section soft"><div class="wrap split"><div><span class="eyebrow">People · Solutions · Progress</span><h2>A practical partner for your stationery requirements.</h2><p>Lepetse Business Enterprise and Projects (Pty) Ltd brings its stationery offering to offices, education buyers and public-sector procurement teams.</p><p>Share the detail that matters to your organisation. Product specifications, availability and delivery arrangements should be confirmed in your quotation.</p><a class="text-link" href="#about">Meet Lepetse ↗</a></div><div class="block-navy"><span class="eyebrow">A better brief makes a better quote</span><h3>Before you send your list</h3><ul><li>Include quantities and pack sizes.</li><li>Tell us where the order needs to go.</li><li>Share your required date and any formal RFQ deadline.</li></ul><a class="btn" href="#quote">Prepare your request ↗</a></div></div></section>${cta()}`}
const buyerPages={business:{label:'Business stationery supply',title:'Keep your office ready for what’s next.',intro:'A clear route for once-off stationery lists, bulk requirements and regular office replenishment.',list:['Paper, pens, files and everyday office essentials','Consolidated requirements across teams or cost centres','Once-off orders or a proposed replenishment schedule','Location and delivery needs captured with your request'],heading:'Make the everyday order easier.',text:'Send one list with the specifications your team uses. Include brands where required, acceptable alternatives and pack quantities, so the quotation can be prepared on a consistent basis.',extra:'For repeat supply, share your likely ordering frequency and typical basket. Payment terms, availability and delivery arrangements must be agreed for the order.'},government:{label:'Government procurement',title:'Start with the specification.<br>Keep the process clear.',intro:'Share formal stationery RFQs and tender requirements for assessment against supply capacity, deadlines and the prescribed response process.',list:['Institution name and RFQ or tender reference','Full specification schedule and required quantities','Closing date and time, briefing requirements and addenda','Official submission instructions and delivery locations'],heading:'Support your procurement process with a complete brief.',text:'Send the original RFQ documents alongside the stationery list. Lepetse must review the requirements and confirm whether it can respond. Mandatory schedules and the institution’s submission rules govern any bid.',extra:'Submitting an RFQ through this prototype does not submit a bid to a government institution. CSD, tax and B-BBEE evidence must be verified and supplied through an appropriate channel; no registration or appointment is claimed here.'},schools:{label:'School and education stationery',title:'Ready for learning.<br>One list at a time.',intro:'Exercise books, writing essentials, geometry sets and school stationery packs organised around your education requirements.',list:['Grade, class or programme stationery lists','Learner or pack quantities and contents per pack','Brand specifications and acceptable alternatives','Assembly, labelling and delivery requirements'],heading:'Turn the school list into a clear requirement.',text:'Attach your approved list and indicate whether quantities are per learner, per class or for the whole school. Include the number of packs and any specific book sizes, page counts or calculator models.',extra:'Share required dates early. Pack contents, assembly capacity, availability and delivery timing must be confirmed before an order is accepted.'}};
function buyerPage(type){const p=buyerPages[type];return `<section class="page-hero"><div class="wrap"><span class="eyebrow">${p.label}</span><h1>${p.title}</h1><p>${p.intro}</p><a class="btn dark" href="#quote" data-buyer="${type}">Prepare a ${type==='government'?'government RFQ':'quote request'} ↗</a></div></section><section class="section"><div class="wrap split"><div><h2>${p.heading}</h2><p>${p.text}</p><p class="notice">${p.extra}</p></div><div><span class="eyebrow">What to include</span><ul class="checklist">${p.list.map(x=>`<li>${x}</li>`).join('')}</ul></div></div></section><section class="section soft"><div class="wrap"><span class="eyebrow">Common questions</span><h2>Before you request a quotation.</h2><details><summary>Can we specify a brand or model?</summary><p>Yes. Include the brand, model and technical requirements, and indicate whether alternatives are acceptable. Any substitution needs approval.</p></details><details><summary>Is delivery available to our location?</summary><p>Provide the town, province, postcode and number of sites. Coverage, delivery cost and timing must be confirmed for your quotation.</p></details><details><summary>Does sending a request confirm an order?</summary><p>No. A request is the start of the quotation process. Pricing, stock, terms and order acceptance require confirmation.</p></details></div></section>${cta()}`}
function pageHero(label,title,text){return `<section class="page-hero"><div class="wrap"><span class="eyebrow">${label}</span><h1>${title}</h1><p>${text}</p></div></section>`}
function input(name,label,type='text',required=true,opts=''){const val=esc(formData[name]);return `<div class="field"><label for="${name}">${label}${required?' *':''}</label>${type==='select'?`<select name="${name}" id="${name}" ${required?'required':''}><option value="">Select an option</option>${opts.split('|').map(o=>`<option ${formData[name]===o?'selected':''}>${o}</option>`).join('')}</select>`:`<input id="${name}" name="${name}" type="${type}" value="${val}" ${required?'required':''}>`}</div>`}
function quote(){return `${pageHero('Request a quotation','Your requirements.<br>Clearly captured.','Prepare your stationery enquiry in four steps. Required fields are marked with an asterisk.')}<section class="section"><div class="wrap rfq-layout"><div><div class="notice">Prototype mode: this form prepares a downloadable enquiry. It does not send your details or files to Lepetse. Use sample information while exploring.</div><div class="progress" aria-label="Request progress">${['Your details','Your list','Delivery','Review'].map((s,i)=>`<span class="${i===step?'active':''}" ${i===step?'aria-current="step"':''}>0${i+1} ${s}</span>`).join('')}</div><form id="rfq" novalidate><div id="form-content"></div><p id="form-error" class="error" role="alert"></p><div class="form-actions"><button class="btn outline" type="button" id="back">${step===0?'Browse stationery':'Back'}</button><button class="btn dark" type="submit">${step===3?'Prepare request summary ↓':'Continue →'}</button></div></form></div><aside class="rfq-aside"><span class="eyebrow">A helpful checklist</span><h3>Before you begin</h3><ol><li>Have your list or specifications ready.</li><li>Check quantities and pack sizes.</li><li>Know the delivery location and date.</li><li>For formal RFQs, include the reference and deadline.</li></ol><p>Prefer to talk?</p><a href="tel:+27794404142">079 440 4142</a><p><a href="mailto:admin@lepetse.co.za">admin@lepetse.co.za</a></p><p class="help">Contact details from the supplied poster; confirmation is part of launch preparation.</p></aside></div></section>`}
function lineRows(){return items.map((x,i)=>`<div class="line-item"><div class="fields"><div class="field"><label for="desc${i}">Item description *</label><input id="desc${i}" data-line="${i}" data-key="description" value="${esc(x.description)}" placeholder="e.g. A4 paper, 80 gsm"></div><div class="field"><label for="qty${i}">Quantity *</label><input id="qty${i}" data-line="${i}" data-key="quantity" type="number" min="1" step="1" value="${esc(x.quantity)}"></div><div class="field"><label for="unit${i}">Unit / pack *</label><input id="unit${i}" data-line="${i}" data-key="unit" value="${esc(x.unit)}" placeholder="e.g. ream of 500"></div></div><button class="remove" type="button" data-remove="${i}">Remove item</button></div>`).join('')}
function renderStep(){if(!$('#form-content'))return;let h='';if(step===0)h=`<fieldset class="form-section"><legend>Tell us about your organisation</legend><div class="fields">${input('organisation','Organisation')}${input('buyerType','Buyer type','select',true,'Private business|Government / public entity|School / education|NGO|Other')}${input('contact','Contact person')}${input('email','Email address','email')}${input('phone','Telephone','tel',false)}${input('orderType','Order type','select',true,'Once-off requirement|Recurring office supply|School / project packs')}</div></fieldset>`;
if(step===1)h=`<fieldset class="form-section"><legend>What do you need?</legend><p class="help">Add complete item rows, attach a list, or do both. Category selections are starting points: confirm the specification, quantity and pack size.</p><div id="lines">${lineRows()}</div><button class="btn outline" type="button" id="add-line">＋ Add an item</button><div class="upload"><label for="files">Attach a stationery list</label><p class="help">Up to 5 files, 10 MB each. PDF, XLSX, CSV, DOCX, JPG or PNG. Files remain on your device in this prototype.</p><input id="files" type="file" multiple accept=".pdf,.xlsx,.csv,.docx,.jpg,.jpeg,.png"><div id="file-list" class="help">${selectedFiles.map(f=>esc(f.name)).join('<br>')}</div><button type="button" class="text-link" id="clear-files" style="border:0;background:none;padding:8px 0">Clear attachments</button></div><div class="fields" style="margin-top:20px">${input('alternatives','Are alternatives acceptable?','select',true,'Yes, subject to approval|No, exact specifications only|Please discuss')}<div class="field full"><label for="notes">Specifications or additional notes</label><textarea id="notes" name="notes">${esc(formData.notes)}</textarea></div></div></fieldset>`;
if(step===2)h=`<fieldset class="form-section"><legend>Where and when?</legend><div class="fields">${input('town','Delivery town / city')}${input('province','Province','select',true,'Eastern Cape|Free State|Gauteng|KwaZulu-Natal|Limpopo|Mpumalanga|North West|Northern Cape|Western Cape')}${input('postcode','Postcode')}${input('sites','Number of delivery sites','number')}${input('date','Required date','date')}${input('timing','Date flexibility','select',true,'Required on this date|Flexible, please discuss')}</div>${formData.buyerType==='Government / public entity'?`<h3>Formal RFQ details</h3><div class="fields">${input('reference','RFQ / tender reference')}${input('deadline','Closing date and time SAST','datetime-local')}${input('channel','Official submission channel')}${input('briefing','Mandatory briefing','select',true,'No|Yes, see RFQ documents|To be confirmed')}</div><p class="help">Attach the original RFQ on the previous step. Include addenda and briefing details in your notes.</p>`:''}</fieldset>`;
if(step===3)h=`<fieldset class="form-section"><legend>Review your request</legend><div class="review-group"><h3>Buyer</h3><p>${esc(formData.organisation)} · ${esc(formData.buyerType)}<br>${esc(formData.contact)} · ${esc(formData.email)}<br>${esc(formData.phone||'No telephone supplied')}<br>${esc(formData.orderType)}</p></div><div class="review-group"><h3>Stationery list</h3>${items.length?items.map(x=>`<p>${esc(x.quantity)} × ${esc(x.description)} — ${esc(x.unit)}</p>`).join(''):'<p>Requirements provided in attached list.</p>'}<p>Alternatives: ${esc(formData.alternatives)}</p><p>${esc(formData.notes)}</p><p>Attachments: ${selectedFiles.length?selectedFiles.map(x=>esc(x.name)).join(', '):'None'}</p></div><div class="review-group"><h3>Delivery and timing</h3><p>${esc(formData.town)}, ${esc(formData.province)}, ${esc(formData.postcode)}<br>${esc(formData.sites)} site(s) · ${esc(formData.date)}<br>${esc(formData.timing)}</p>${formData.buyerType==='Government / public entity'?`<p>RFQ: ${esc(formData.reference)}<br>Closes: ${esc(formData.deadline?.replace('T',' '))} SAST<br>Channel: ${esc(formData.channel)}<br>Briefing: ${esc(formData.briefing)}</p>`:''}</div><p class="help">This prototype processes the information in your browser only. The downloaded summary includes file names, not the files themselves. No stock, price, delivery date or order is confirmed.</p></fieldset>`;
$('#form-content').innerHTML=h;$('#back').onclick=()=>{capture();if(step===0)location.hash='stationery';else{step--;renderQuote()}};
$('#add-line')?.addEventListener('click',()=>{capture();items.push({description:'',quantity:1,unit:''});renderStep();updateCount()});$('#files')?.addEventListener('change',e=>{const files=[...e.target.files];const allowed=/\.(pdf|xlsx|csv|docx|jpe?g|png)$/i;if(files.length>5||files.some(f=>f.size>10*1024*1024||!allowed.test(f.name))){e.target.value='';$('#form-error').textContent='Choose up to five supported files, each no larger than 10 MB.';return}selectedFiles=files;$('#file-list').textContent=files.map(f=>f.name).join(', ');$('#form-error').textContent=''});$('#clear-files')?.addEventListener('click',()=>{selectedFiles=[];$('#files').value='';$('#file-list').textContent=''});
$('#lines')?.addEventListener('click',e=>{if(e.target.dataset.remove!==undefined){capture();items.splice(Number(e.target.dataset.remove),1);renderStep();updateCount()}});$('#rfq').onsubmit=e=>{e.preventDefault();capture();if(!validate())return;if(step<3){step++;renderQuote()}else finish()};}
function capture(){const form=$('#rfq');if(!form)return;new FormData(form).forEach((v,k)=>{if(typeof v==='string')formData[k]=v.trim()});form.querySelectorAll('[data-line]').forEach(e=>{items[Number(e.dataset.line)][e.dataset.key]=e.value.trim()})}
function validate(){const bad=[...$('#rfq').querySelectorAll('[required]')].find(e=>!e.checkValidity());if(bad){$('#form-error').textContent='Please complete the required fields using valid details.';bad.reportValidity();return false}let err='';if(step===1){if(!items.length&&!selectedFiles.length)err='Add at least one item or attach your stationery list.';else if(items.some(i=>!i.description||!i.unit||!Number.isInteger(Number(i.quantity))||Number(i.quantity)<1))err='Complete each item with a description, positive whole quantity and unit or pack size, or remove unused rows.'}if(step===2){if(!/^\d{4}$/.test(formData.postcode))err='Enter a four-digit South African postcode.';else if(!Number.isInteger(Number(formData.sites))||Number(formData.sites)<1)err='Enter a positive whole number of delivery sites.';else if(formData.date<new Date().toLocaleDateString('en-CA',{timeZone:'Africa/Johannesburg'}))err='Select a future required date.';else if(formData.deadline&&formData.buyerType==='Government / public entity'&&new Date(formData.deadline+'+02:00')<=new Date())err='The closing deadline has passed. Check the date and time.'}$('#form-error').textContent=err;return !err}
function renderQuote(){main.innerHTML=quote();renderStep();bindCommon();$('#rfq')?.scrollIntoView({block:'start',behavior:'smooth'})}
function finish(){const summary={prototype:true,sent:false,preparedAt:new Date().toISOString(),buyer:formData,items,attachments:selectedFiles.map(f=>({name:f.name,size:f.size})),note:'Prepared on device. Not submitted to Lepetse. Attach original files separately if sending an enquiry.'};main.innerHTML=pageHero('Request prepared','Your summary is ready.','Nothing has been sent to Lepetse.')+`<section class="section"><div class="wrap content success"><h2>Review complete.</h2><p>Download the enquiry summary for review. It contains your details and item list, plus the names of selected files. The original attachments are not included.</p><p>To make a real enquiry, contact Lepetse separately and attach your documents. This prototype has no live submission service.</p><button class="btn dark" id="download">Download enquiry summary</button><button class="btn outline" id="edit">Edit this request</button><a class="btn outline" href="#contact">Contact details</a></div></section>`;$('#download').onclick=()=>{const blob=new Blob([JSON.stringify(summary,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='lepetse-enquiry-draft.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#edit').onclick=()=>{step=0;renderQuote()};main.focus();window.scrollTo(0,0)}
function bindCommon(){main.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{const c=categories.find(c=>c[2]===b.dataset.add);items.push({description:c[0],quantity:1,unit:''});updateCount();toast(`${c[0]} added. Specify the items in your quote list.`)});main.querySelectorAll('[data-buyer]').forEach(a=>a.onclick=()=>{step=0;formData.buyerType={business:'Private business',government:'Government / public entity',schools:'School / education'}[a.dataset.buyer]})}
function render(){const route=location.hash.slice(1)||'home';document.querySelector('nav').classList.remove('open');$('.menu').setAttribute('aria-expanded','false');document.querySelectorAll('nav a').forEach(a=>{if(a.hash===`#${route}`)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(route==='home')main.innerHTML=home();else if(buyerPages[route])main.innerHTML=buyerPage(route);else if(route==='stationery'){main.innerHTML=pageHero('Stationery categories','The essentials, all in one place.','Explore the categories and add a starting point to your quote list. Product availability and exact specifications require confirmation.')+`<section class="section"><div class="wrap"><label for="search" class="help">Find a category</label><input class="search" id="search" type="search" placeholder="Search paper, books, calculators…"><div class="category-grid" id="catalogue">${cards()}</div><p class="help">Category illustrations are representative. No live stock or prices are shown.</p></div></section>`+cta();$('#search').oninput=e=>{$('#catalogue').innerHTML=cards(e.target.value)||'<p class="empty">No matching category. Describe your requirement in the quote form.</p>';bindCommon()}}else if(route==='quote'){main.innerHTML=quote();renderStep()}else if(route==='about')main.innerHTML=pageHero('About Lepetse','People. Solutions. Progress.','Lepetse Business Enterprise and Projects (Pty) Ltd — stationery for organisations, offices and classrooms.')+`<section class="section"><div class="wrap split"><div><h2>Everyday supplies.<br>A practical starting point.</h2><p>Lepetse’s stationery offering includes school packs, books, writing essentials, paper, office supplies, art materials, geometry sets and calculators.</p><p>This website brings those categories together with a structured way for private and government buyers to share their requirements.</p><a class="text-link" href="#contact">Talk about your requirements ↗</a></div><div class="block-navy"><span class="eyebrow">Our approach</span><h3>Clarity before commitment.</h3><p>Start with the specification. Confirm quantities and pack sizes. Agree pricing, delivery and terms before the order proceeds.</p></div></div></section>`+cta();else if(route==='contact')main.innerHTML=pageHero('Contact Lepetse','Let’s start with your list.','For stationery requirements, supplier information or delivery enquiries, use the contacts below.')+`<section class="section"><div class="wrap split"><div class="contact-list"><span class="eyebrow">Call or WhatsApp</span><a href="tel:+27794404142">079 440 4142</a><a class="btn outline" href="https://wa.me/27794404142" target="_blank" rel="noopener">Open WhatsApp ↗</a><p class="eyebrow" style="margin-top:30px">Email</p><a href="mailto:admin@lepetse.co.za">admin@lepetse.co.za</a></div><div><h2>Tell us where you need it.</h2><p>Include your town, province, postcode and required date so delivery coverage and arrangements can be checked.</p><div class="notice">Contacts are transcribed from the supplied business poster. Operating hours, physical address and delivery coverage are awaiting confirmation for launch.</div><a class="btn dark" href="#quote">Prepare an enquiry ↗</a></div></div></section>`;else if(route==='privacy')main.innerHTML=pageHero('Prototype information','Your details stay on this device.','This is a review prototype, not a live customer procurement service.')+`<section class="section"><div class="wrap content"><h2>How the prototype handles information</h2><p>The quotation form holds entered details and selected file names temporarily in browser memory. It does not upload attachments, send enquiries, create accounts or store form details in local storage. Reloading the page clears the request.</p><p>If you download a summary, that file contains the information you entered. Keep it secure and remove sample downloads when no longer needed. Hosting infrastructure may process ordinary access logs.</p><p>Telephone, email and WhatsApp links open external services. Information you choose to send there is handled by those services and the recipient.</p><h3>Before the public launch</h3><p>A live form requires secure storage and upload scanning, staff notifications, an approved privacy notice, retention rules and tested access controls. Legal identity, registrations, delivery coverage, trading terms and supplier documents also need verification.</p><p>For business enquiries, contact <a href="mailto:admin@lepetse.co.za">admin@lepetse.co.za</a>.</p></div></section>`;else main.innerHTML=pageHero('Page not found','Let’s get you back on track.','Use the navigation to explore stationery or prepare an enquiry.')+cta();
bindCommon();updateCount();document.title=`${({home:'Stationery for the work ahead',stationery:'Stationery categories',quote:'Request a quote',business:'Business supply',government:'Government procurement',schools:'School stationery',about:'About',contact:'Contact',privacy:'Prototype privacy'})[route]||'Page'} | Lepetse`;window.scrollTo(0,0);}
$('.menu').onclick=()=>{const open=document.querySelector('nav').classList.toggle('open');$('.menu').setAttribute('aria-expanded',String(open))};window.addEventListener('hashchange',()=>{capture();render()});render();
